fn solve(input: Vec<i8>) -> Vec<&'static str> {
    let t = input[0] as usize;
    let mut result = Vec::with_capacity(t);
    
    for i in 1..=t {
        let n = input[i] as i32;  // Convert to i32 for easier calculations
        
        match n {
            1 => result.push("FastestFinger"),
            2 => result.push("Ashishgup"),
            _ => {
                // Check if n is a power of two
                if n.is_power_of_two() {
                    result.push("FastestFinger");
                } else if n % 4 != 2 {
                    result.push("Ashishgup");
                } else {
                    // n % 4 == 2
                    let p = n / 2;
                    
                    // Check if p is "limited-prime"
                    let is_prime = match p {
                        x if x <= 1 => false,
                        2 => true,
                        x if x % 2 == 0 => false,  // even > 2
                        _ => true,  // odd > 2
                    };
                    
                    if is_prime {
                        result.push("FastestFinger");
                    } else {
                        result.push("Ashishgup");
                    }
                }
            }
        }
    }
    
    result
}